groupButtonf1mwztqves.onClick:
{{
  (async () => {
    try {
      const mode =
        appsmith.store.cp_form_mode ||
        "NEW";

      const tenantId =
        appsmith.store.cp_tenant_id ||
        appsmith.store.tenant_id ||
        appsmith.store.current_user?.tenant_id ||
        null;

      const userId =
        appsmith.store.user_id ||
        appsmith.store.current_user?.id ||
        null;

      /*
       * =========================================================
       * 1. VALIDACIÓN DEL CONTEXTO
       * =========================================================
       */

      if (!appsmith.store.cp_exportacion_id) {
        showAlert(
          "SELECCIONE UNA OPERACIÓN.",
          "warning"
        );
        return false;
      }

      if (!tenantId) {
        showAlert(
          "NO SE ENCONTRÓ EL TENANT DE LA OPERACIÓN.",
          "error"
        );
        return false;
      }

      if (!userId) {
        showAlert(
          "NO SE ENCONTRÓ EL USUARIO AUTENTICADO.",
          "error"
        );
        return false;
      }

      if (
        !["NEW", "EDIT", "DUPLICATE"].includes(mode)
      ) {
        showAlert(
          "EL FORMULARIO NO ESTÁ EN UN MODO VÁLIDO PARA GUARDAR.",
          "error"
        );
        return false;
      }

      if (
        mode === "EDIT" &&
        !appsmith.store.cp_vehiculo_edit_id
      ) {
        showAlert(
          "NO SE ENCONTRÓ EL VIAJE QUE SE DESEA ACTUALIZAR.",
          "error"
        );
        return false;
      }

      /*
       * En modo DUPLICATE debe existir la trazabilidad
       * del viaje que fue copiado.
       */
      if (
        mode === "DUPLICATE" &&
        !appsmith.store.cp_duplicate_source
      ) {
        showAlert(
          "NO SE ENCONTRÓ EL VIAJE DE ORIGEN DE LA DUPLICACIÓN.",
          "error"
        );
        return false;
      }

      /*
       * =========================================================
       * 2. VALIDACIÓN DEL VEHÍCULO
       * =========================================================
       */

      const placa = String(
        inpCpPlaca.text || ""
      )
        .trim()
        .toUpperCase();

      if (!placa) {
        showAlert(
          "DEBE DIGITAR LA PLACA DEL VEHÍCULO.",
          "warning"
        );
        return false;
      }

      if (!slCpTipoVehiculo.selectedOptionValue) {
        showAlert(
          "DEBE SELECCIONAR EL TIPO DE VEHÍCULO.",
          "warning"
        );
        return false;
      }

      if (!slCpMarcaVehiculo.selectedOptionValue) {
        showAlert(
          "DEBE SELECCIONAR LA MARCA DEL VEHÍCULO.",
          "warning"
        );
        return false;
      }

      if (
        !String(
          inpCpModeloVehiculo.text || ""
        ).trim()
      ) {
        showAlert(
          "DEBE DIGITAR EL MODELO DEL VEHÍCULO.",
          "warning"
        );
        return false;
      }

      if (!slCpColorVehiculo.selectedOptionValue) {
        showAlert(
          "DEBE SELECCIONAR EL COLOR DEL VEHÍCULO.",
          "warning"
        );
        return false;
      }

      const capacidadKg = Number(
        String(
          inpCpCapacidadCargaKg.text || ""
        )
          .trim()
          .replace(",", ".")
      );

      if (
        !Number.isFinite(capacidadKg) ||
        capacidadKg <= 0
      ) {
        showAlert(
          "LA CAPACIDAD DE CARGA DEBE SER MAYOR QUE CERO.",
          "warning"
        );
        return false;
      }

      if (
        !String(
          inpCpSoatNo.text || ""
        ).trim()
      ) {
        showAlert(
          "DEBE DIGITAR EL NÚMERO DEL SOAT.",
          "warning"
        );
        return false;
      }

      if (!dpCpSoatVencimiento.selectedDate) {
        showAlert(
          "DEBE SELECCIONAR LA FECHA DE VENCIMIENTO DEL SOAT.",
          "warning"
        );
        return false;
      }

      /*
       * =========================================================
       * 3. VALIDACIÓN DEL REMOLQUE
       * =========================================================
       */

      const tipoRemolqueId =
        slCpTipoRemolque.selectedOptionValue ||
        null;

      const tipoRemolqueLabel = String(
        slCpTipoRemolque.selectedOptionLabel ||
        ""
      )
        .trim()
        .toUpperCase();

      const placaRemolque = String(
        inpCpPlacaRemolque.text || ""
      )
        .trim()
        .toUpperCase();

      if (
        tipoRemolqueId &&
        tipoRemolqueLabel !== "NO APLICA" &&
        !placaRemolque
      ) {
        showAlert(
          "DEBE DIGITAR LA PLACA DEL REMOLQUE.",
          "warning"
        );
        return false;
      }

      /*
       * =========================================================
       * 4. VALIDACIÓN DEL CONDUCTOR
       * =========================================================
       */

      const documentoConductor = String(
        inpCpCedulaConductor.text || ""
      ).trim();

      if (!documentoConductor) {
        showAlert(
          "DEBE DIGITAR EL DOCUMENTO DEL CONDUCTOR.",
          "warning"
        );
        return false;
      }

      if (
        !String(
          inpCpNombreConductor.text || ""
        ).trim()
      ) {
        showAlert(
          "DEBE REGISTRAR EL NOMBRE DEL CONDUCTOR.",
          "warning"
        );
        return false;
      }

      if (
        !String(
          inpCpLicenciaConductor.text || ""
        ).trim()
      ) {
        showAlert(
          "DEBE REGISTRAR LA LICENCIA DEL CONDUCTOR.",
          "warning"
        );
        return false;
      }

      if (
        !String(
          inpCpTelefonoConductor.text || ""
        ).trim()
      ) {
        showAlert(
          "DEBE REGISTRAR EL TELÉFONO DEL CONDUCTOR.",
          "warning"
        );
        return false;
      }

      /*
       * =========================================================
       * 5. REVALIDACIÓN DE LOS DIRECTORIOS
       * =========================================================
       *
       * Las queries pueden conservar resultados anteriores.
       * Se ejecutan nuevamente usando los valores actuales.
       */

      await qCpBuscarVehiculoPorPlaca.run();
      await qCpBuscarConductorPorDocumento.run();

      const vehiculoDirectorio =
        qCpBuscarVehiculoPorPlaca.data?.[0] ||
        null;

      const conductorDirectorio =
        qCpBuscarConductorPorDocumento.data?.[0] ||
        null;

      if (!vehiculoDirectorio?.vehiculo_id) {
        showAlert(
          "EL VEHÍCULO NO EXISTE EN EL DIRECTORIO. CRÉELO DESDE ACTUALIZAR VEHÍCULO ANTES DE GUARDAR EL VIAJE.",
          "warning"
        );
        return false;
      }

      if (!conductorDirectorio?.conductor_id) {
        showAlert(
          "EL CONDUCTOR NO EXISTE EN EL DIRECTORIO. CRÉELO DESDE ACTUALIZAR CONDUCTOR ANTES DE GUARDAR EL VIAJE.",
          "warning"
        );
        return false;
      }

      /*
       * =========================================================
       * 6. PERSISTENCIA
       * =========================================================
       */

      let mensajeExito = "";

      if (mode === "EDIT") {
        /*
         * EDIT actualiza exclusivamente el viaje seleccionado.
         */
        await bkCpVehiculoUpdate.run();

        const updated =
          bkCpVehiculoUpdate.data?.[0] ||
          null;

        if (!updated?.cargue_vehiculo_id) {
          showAlert(
            "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ EL VIAJE ACTUALIZADO.",
            "error"
          );
          return false;
        }

        mensajeExito =
          "VEHÍCULO / VIAJE ACTUALIZADO CORRECTAMENTE.";
      } else {
        /*
         * NEW y DUPLICATE generan un registro nuevo.
         *
         * bkCpVehiculoInsert calcula:
         * - nuevo item_no;
         * - nuevo viaje_no por placa;
         * - referencias al vehículo y conductor.
         */

        await bkCpVehiculoInsert.run();

        const inserted =
          bkCpVehiculoInsert.data?.[0] ||
          null;

        if (!inserted?.cargue_vehiculo_id) {
          showAlert(
            "LA QUERY FINALIZÓ, PERO NO DEVOLVIÓ EL VIAJE CREADO.",
            "error"
          );
          return false;
        }

        mensajeExito =
          mode === "DUPLICATE"
            ? "VIAJE DUPLICADO CORRECTAMENTE."
            : "VEHÍCULO / VIAJE REGISTRADO CORRECTAMENTE.";
      }

      /*
       * =========================================================
       * 7. RECARGA DE INFORMACIÓN
       * =========================================================
       */

      if (
        typeof qCpVehiculosResumen !==
          "undefined" &&
        qCpVehiculosResumen?.run
      ) {
        await qCpVehiculosResumen.run();
      }

      if (
        typeof qCpOperacionResumen !==
          "undefined" &&
        qCpOperacionResumen?.run
      ) {
        await qCpOperacionResumen.run();
      }

      /*
       * =========================================================
       * 8. LIMPIEZA FINAL
       * =========================================================
       */

      await JS_CarguePlanta.cancelVehiculoForm();

      showAlert(
        mensajeExito,
        "success"
      );

      return true;

    } catch (error) {
      console.error(
        "ERROR AL GUARDAR VEHÍCULO / VIAJE:",
        error
      );

      const mensajeError =
        error?.message ||
        error?.error ||
        "ERROR NO IDENTIFICADO";

      showAlert(
        "NO SE PUDO GUARDAR EL VEHÍCULO / VIAJE: " +
          mensajeError,
        "error"
      );

      return false;
    }
  })()
}}

groupButtonn15izot6di.onClick:
{{
  (() => {
    const row = tblCpVehiculos.selectedRow || null;
    const id = row?.cargue_vehiculo_id || row?.id || null;

    if (!row || !id) {
      showAlert("SELECCIONE UN VEHÍCULO / VIAJE EN LA TABLA.", "warning");
      return;
    }

    storeValue("cp_vehiculo_selected", row);
    storeValue("cp_vehiculo_selected_id", id);

    storeValue("cp_delete_context", {
      id: id,
      item_no: row.item_no,
      viaje_no: row.viaje_no,
      placa: row.placa,
      conductor_nombre: row.conductor_nombre
    });

    showModal("mdlCpDeleteVehiculo");
  })()
}}

